BEGIN
  -- Only on a database being built from scratch: its first seed ran after this
  -- snapshot was taken. Production, seeded since August, skips the whole file.
  IF (SELECT min(run_at) FROM seed_history) < timestamptz '2026-10-26 00:00:00+00' THEN
    RETURN;
  END IF;
-- study_item_facets: 32603 rows
END
$seed$;
